b=Book('14.1',list(range(984,990)))
def add(n,st,steps,ans,parts=[],topic=('다변수함수와 그래프','Functions of several variables')):b.add(n,984 if n<=17 else 985 if n<=31 else 986 if n<=36 else 987 if n<=60 else 988 if n<=70 else 989,topic,st,steps,ans,parts)
def eq(n,F,A,detail,parts=[]):add(n,(r'\('+F+r'\). '+detail[0],r'\('+F+r'\). '+detail[1]),[('주어진 값을 순서대로 대입하고 정의역의 조건을 함께 확인한다.','Substitute the indicated values and retain the domain restrictions.')]+fs(A),same(r'\['+A+r'\]'),parts)
eq(1,r'f(x,y)=\frac{x^2y}{2x-y^2}',r'(a)\ -3/7,\quad(b)\ 4/5,\quad(c)\ \frac{(x+h)^2y}{2(x+h)-y^2},\quad(d)\ \frac{x^2}{2-x}\ (x\ne0,2)',('f(1,3), f(-2,-1), f(x+h,y), f(x,x)를 구하라.','Find f(1,3), f(-2,-1), f(x+h,y), and f(x,x).'),list('abcd'))
eq(2,r'g(x,y)=x\sin y+y\sin x',r'(a)\ 0,\quad(b)\frac{\pi\sqrt2}4+\frac\pi4,\quad(c)\ 0,\quad(d)\ x\sin(y+h)+(y+h)\sin x',('g(π,0), g(π/2,π/4), g(0,y), g(x,y+h)를 구하라.','Find g(π,0), g(π/2,π/4), g(0,y), and g(x,y+h).'),list('abcd'))
add(3,(r'\(g=x^2\ln(x+y)\). (a) g(3,1), (b) 정의역과 그림, (c) 치역을 구하라.',r'For \(g=x^2\ln(x+y)\), find (a) g(3,1), (b) its domain and sketch, and (c) its range.'),fs(r'g(3,1)=9\ln4',r'x+y>0\iff y>-x')+[('x=1로 고정하면 y>-1에서 ln(1+y)가 모든 실숫값을 갖는다.','With x=1, ln(1+y) attains every real value as y ranges above -1.')],same(r'(a) (9ln4); (b) (y>-x), 경계 제외 / boundary excluded; (c) (mathbb R).'),list('abc'))
add(4,(r'\(h=e^{\sqrt{y-x^2}}\). (a) h(-2,5), (b) 정의역과 그림, (c) 치역을 구하라.',r'For \(h=e^{\sqrt{y-x^2}}\), find (a) h(-2,5), (b) its domain and sketch, and (c) its range.'),fs(r'h(-2,5)=e,\quad y-x^2\ge0,\quad\sqrt{y-x^2}\in[0,\infty)'),same(r'(a) (e); (b) (yge x^2); (c) ([1,infty)).'),list('abc'))
eq(5,r'F(x,y,z)=\sqrt y-\sqrt{x-2z}',r'F(3,4,1)=1,\quad D=\{y\ge0,\ z\le x/2\}',('값 F(3,4,1)과 정의역을 구하고 공간에서 설명하라.','Evaluate F(3,4,1) and describe its domain in space.'),list('ab'))
eq(6,r'f=\ln(z-\sqrt{x^2+y^2})',r'f(4,-3,6)=\ln1=0,\quad D=\{z>\sqrt{x^2+y^2}\}',('값 f(4,-3,6)과 정의역을 구하라. 정의역은 위쪽 원뿔 내부이며 경계는 제외된다.','Evaluate f(4,-3,6) and describe the domain: inside the upper cone, excluding its boundary.'),list('ab'))
domains={7:(r'\sqrt{x-2}+\sqrt{y-1}',r'x\ge2,\ y\ge1','두 근호가 각각 0 이상인 오른쪽 위 사분면.','The upper-right region where both radicands are nonnegative.'),8:(r'\sqrt[4]{x-3y}',r'y\le x/3','직선 아래의 닫힌 반평면.','The closed half-plane below the line.'),9:(r'\sqrt x+\sqrt{4-4x^2-y^2}',r'x\ge0,\quad4x^2+y^2\le4','타원판의 오른쪽 절반, 모든 경계 포함.','The right half of the closed elliptical disk.'),10:(r'\ln(x^2+y^2-9)',r'x^2+y^2>9','반지름 3인 원 바깥, 원 제외.','Outside the radius-3 circle, excluding the circle.'),11:(r'\frac{x-y}{x+y}',r'x+y\ne0','직선 y=-x를 제외한 평면.','The plane with the line y=-x removed.'),12:(r'\frac{\ln(2-x)}{1-x^2-y^2}',r'x<2,\quad x^2+y^2\ne1','x=2 왼쪽에서 단위원을 제거한다.','Take the region left of x=2 and remove the unit circle.'),13:(r'\frac{\sqrt{xy}}{x+1}',r'xy\ge0,\quad x\ne-1','제1·3사분면 및 좌표축에서 x=-1인 점을 제거한다.','The first/third quadrants and axes, with points at x=-1 removed.'),14:(r'\arcsin(x+y)',r'-1\le x+y\le1','두 평행선 사이의 닫힌 띠.','The closed strip between two parallel lines.'),15:(r'\sqrt{4-x^2}+\sqrt{9-y^2}+\sqrt{1-z^2}',r'|x|\le2,\ |y|\le3,\ |z|\le1','닫힌 직육면체.','A closed rectangular box.'),16:(r'\ln(16-4x^2-4y^2-z^2)',r'4x^2+4y^2+z^2<16','반축 2,2,4인 타원체 내부, 표면 제외.','The interior of an ellipsoid with semiaxes 2,2,4; exclude its surface.')}
for n,(F,D,k,e)in domains.items():add(n,(r'\(f='+F+r'\)의 정의역을 구하고 그려라.',r'Find and sketch the domain of \(f='+F+r'\).'),[('짝수근의 내부는 0 이상, 로그의 내부는 양수, 분모는 0이 아니어야 한다. 역사인의 입력은 [-1,1]이다.','Require even radicands to be nonnegative, logarithm arguments positive, denominators nonzero, and arcsine inputs in [-1,1].')]+fs(D)+[(k,e)],(r'\('+D+r'\). '+k,r'\('+D+r'\). '+e))
S=.1091*160**.425*70**.725
add(17,(r'체표면적 모델 \(S=.1091w^{.425}h^{.725}\)에서 w는 lb, h는 in, S는 ft²이다. (a) f(160,70)의 값과 의미, (b) 자신의 치수를 이용한 값을 구하라.',r'For body area \(S=.1091w^{.425}h^{.725}\), with w in lb, h in in, and S in ft², (a) interpret f(160,70); (b) use your own measurements.'),fs(r'S=.1091(160)^{.425}(70)^{.725}\approx'+f'{S:.4f}')+[('자신의 양의 체중과 키를 같은 단위로 바꾸어 식에 넣는다. 개인 치수가 없으면 수치는 정해지지 않는다.','Convert your positive weight and height to the stated units and substitute. No unique personal value is determined without measurements.')],('160 lb, 70 in인 사람은 약 20.5 ft². (b)는 개인 치수에 따라 달라진다.','About 20.5 ft² for a person weighing 160 lb and standing 70 in. Part (b) depends on personal measurements.'),list('ab'))
